{
  "findings": [
    {
      "check_id": "CKV_AWS_23",
      "title": "Ensure every security group and rule has a description",
      "resource": "aws_security_group.lb",
      "severity": "MEDIUM",
      "explanation": "The security group 'lb' is missing a description, which is a best practice for tracking and auditing purposes."
    },
    {
      "check_id": "CKV_AWS_277",
      "title": "Ensure no security groups allow ingress from 0.0.0.0:0 to port -1",
      "resource": "aws_security_group.lb",
      "severity": "MEDIUM",
      "explanation": "The security group 'lb' allows ingress from 0.0.0.0/0 to all ports, which is overly permissive."
    },
    {
      "check_id": "CKV_AWS_382",
      "title": "Ensure no security groups allow egress from 0.0.0.0:0 to port -1",
      "resource": "aws_security_group.lb",
      "severity": "MEDIUM",
      "explanation": "The security group 'lb' allows egress to 0.0.0.0/0 on all ports, which is overly permissive."
    }
  ],
  "patched_code": "resource \"aws_security_group\" \"lb\" {\n  name        = \"allow-all-lb\"\n  vpc_id      = data.aws_vpc.main.id\n  description = \"Security group for load balancer\"\n  ingress {\n    from_port   = 80\n    to_port     = 80\n    protocol    = \"tcp\"\n    cidr_blocks = [\"0.0.0.0/0\"]\n  }\n  egress {\n    from_port   = 0\n    to_port     = 0\n    protocol    = \"tcp\"\n    cidr_blocks = [\"10.0.0.0/16\"]\n  }\n}",
  "fix_summary": "Added a description to the security group, restricted ingress to port 80, and limited egress to a specific CIDR block on TCP protocol."
}
